//
//  BuiltinDictionaryStore.swift
//  Easydict
//
//  Slim build: read-only access to the bundled dictionary database generated by
//  scripts/builtin-dict/update.sh (ECDICT, JMdict, KANJIDIC2, Kanjium pitch accents).
//  The app ships it LZMA-compressed; the first use extracts it to the cache directory.
//

import Foundation
import SQLite3

// MARK: - BuiltinDictionaryStore

final class BuiltinDictionaryStore: @unchecked Sendable {
    // MARK: Lifecycle

    private init() {}

    deinit {
        sqlite3_close(database)
    }

    // MARK: Internal

    static let shared = BuiltinDictionaryStore()

    /// Whether the database is open. Never waits for an extraction in progress.
    var isReady: Bool {
        readyLock.withLock { ready }
    }

    /// Mirrors `normalize_key` in scripts/builtin-dict/generate.py: NFKC, then katakana to
    /// hiragana, so カタカナ, ｶﾀｶﾅ and かたかな look up the same rows.
    static func normalizedJapaneseKey(_ text: String) -> String {
        let scalars = text.precomposedStringWithCompatibilityMapping.unicodeScalars.map { scalar in
            (0x30A1 ... 0x30F6).contains(scalar.value)
                ? Unicode.Scalar(scalar.value - 0x60) ?? scalar : scalar
        }
        return String(String.UnicodeScalarView(scalars))
    }

    /// Starts extracting and opening the database in the background, if not done yet.
    func prepareInBackground() {
        DispatchQueue.global(qos: .utility).async { [self] in
            _ = withDatabase { _ in () }
        }
    }

    // MARK: English

    /// ECDICT rows whose word matches `word` case-insensitively, exact-case match first.
    func englishEntries(_ word: String) -> [EnglishDictionaryEntry] {
        let key = word.lowercased()
        let entries = query(
            """
            SELECT word, phonetic, translation, definition, pos, collins, oxford, tag, bnc, frq,
                   exchange FROM en WHERE key = ?
            """,
            bindings: [key]
        ) { statement in
            EnglishDictionaryEntry(
                word: statement.text(0), phonetic: statement.text(1),
                translation: statement.text(2), definition: statement.text(3),
                partOfSpeech: statement.text(4), collins: statement.int(5),
                isOxford3000: statement.int(6) > 0, tags: statement.text(7),
                bncRank: statement.int(8), frequencyRank: statement.int(9),
                exchange: statement.text(10)
            )
        }
        return entries.sorted { lhs, rhs in lhs.word == word && rhs.word != word }
    }

    /// Dictionary forms that `form` is an inflection of, e.g. `ran` → `run`.
    func englishLemmas(ofForm form: String) -> [String] {
        query("SELECT DISTINCT word FROM en_form WHERE form = ?", bindings: [form.lowercased()]) {
            $0.text(0)
        }
    }

    // MARK: Japanese

    /// JMdict entries with a written form or reading equal to `text` (after normalization).
    func japaneseEntries(_ text: String) -> [JapaneseDictionaryEntry] {
        let key = Self.normalizedJapaneseKey(text)
        return query(
            """
            SELECT ja.id, ja.common, ja.entry, MAX(ja_key.kana) FROM ja_key
            JOIN ja ON ja.id = ja_key.id WHERE ja_key.key = ? GROUP BY ja.id
            """,
            bindings: [key]
        ) { statement in
            JapaneseDictionaryEntry(
                id: statement.int(0), isCommon: statement.int(1) > 0,
                json: statement.text(2), matchedReading: statement.int(3) > 0
            )
        }.compactMap { $0 }
    }

    /// KANJIDIC2 data for each kanji in `text`, in order and without duplicates.
    func kanji(in text: String) -> [KanjiDictionaryEntry] {
        var seen = Set<Character>()
        return text.filter { $0.isKanji && seen.insert($0).inserted }.compactMap { character in
            query("SELECT entry FROM kanji WHERE literal = ?", bindings: [String(character)]) {
                KanjiDictionaryEntry(literal: String(character), json: $0.text(0))
            }.first ?? nil
        }
    }

    // MARK: Private

    private static let resourceName = "builtin-dictionary.sqlite"
    private static let schemaVersion = 1

    private static let transient = unsafeBitCast(-1, to: sqlite3_destructor_type.self)

    private static var cacheDirectory: URL {
        AppPathManager.current.cacheDirectory
            .appendingPathComponent("builtin-dictionary", isDirectory: true)
    }

    private let lock = NSLock()
    private let readyLock = NSLock()
    private var ready = false
    private var database: OpaquePointer?
    private var didFailToOpen = false

    private func query<Row>(
        _ sql: String,
        bindings: [String],
        row: (Statement) -> Row
    )
        -> [Row] {
        withDatabase { database in
            var handle: OpaquePointer?
            guard sqlite3_prepare_v2(database, sql, -1, &handle, nil) == SQLITE_OK, let handle else {
                logError("Built-in dictionary query failed: \(String(cString: sqlite3_errmsg(database)))")
                return []
            }
            defer { sqlite3_finalize(handle) }

            for (index, value) in bindings.enumerated() {
                sqlite3_bind_text(handle, Int32(index + 1), value, -1, Self.transient)
            }
            var rows: [Row] = []
            while sqlite3_step(handle) == SQLITE_ROW {
                rows.append(row(Statement(handle: handle)))
            }
            return rows
        } ?? []
    }

    /// Runs `body` with the open database, extracting and opening it first if needed. All
    /// access is serialized by `lock`, so the shared connection is never used concurrently.
    private func withDatabase<T>(_ body: (OpaquePointer) -> T) -> T? {
        lock.withLock {
            if database == nil, !didFailToOpen {
                database = openDatabase()
                didFailToOpen = database == nil
                readyLock.withLock { ready = database != nil }
            }
            return database.map(body)
        }
    }

    private func openDatabase() -> OpaquePointer? {
        let start = CFAbsoluteTimeGetCurrent()
        guard let url = extractedDatabaseURL() else { return nil }

        var database: OpaquePointer?
        let flags = SQLITE_OPEN_READONLY | SQLITE_OPEN_NOMUTEX
        guard sqlite3_open_v2(url.path, &database, flags, nil) == SQLITE_OK else {
            logError("Built-in dictionary could not be opened at \(url.path)")
            sqlite3_close(database)
            return nil
        }
        logInfo(String(format: "Built-in dictionary ready in %.2f s", CFAbsoluteTimeGetCurrent() - start))
        return database
    }

    /// The extracted database for this build, extracting it from the app bundle if needed.
    /// Extracted copies from other builds are removed.
    private func extractedDatabaseURL() -> URL? {
        guard let resourceURL = Bundle.main.url(forResource: Self.resourceName, withExtension: "xz"),
              let size = try? resourceURL.resourceValues(forKeys: [.fileSizeKey]).fileSize
        else {
            logError("Built-in dictionary resource is missing")
            return nil
        }

        // Extract again for every build, so regenerated data is never mistaken for the old one.
        let build = Bundle.main.object(forInfoDictionaryKey: "CFBundleVersion") as? String ?? "0"
        let directory = Self.cacheDirectory
        let fileName = "dictionary-v\(Self.schemaVersion)-\(build)-\(size).sqlite"
        let url = directory.appendingPathComponent(fileName)
        if FileManager.default.fileExists(atPath: url.path) {
            return url
        }

        do {
            try AppPathManager.current.ensureDirectoryExists(at: directory)
            let compressed = try Data(contentsOf: resourceURL, options: .mappedIfSafe)
            let data = try (compressed as NSData).decompressed(using: .lzma) as Data
            let temporaryURL = directory.appendingPathComponent("\(fileName).partial")
            try data.write(to: temporaryURL, options: .atomic)
            try FileManager.default.moveItem(at: temporaryURL, to: url)
        } catch {
            logError("Built-in dictionary extraction failed: \(error)")
            return nil
        }

        let staleFiles = (try? FileManager.default.contentsOfDirectory(atPath: directory.path)) ?? []
        for name in staleFiles where name != fileName {
            try? FileManager.default.removeItem(at: directory.appendingPathComponent(name))
        }
        return url
    }
}

// MARK: - Statement

/// Column accessors for the current row of a prepared statement.
private struct Statement {
    let handle: OpaquePointer

    func text(_ column: Int32) -> String {
        sqlite3_column_text(handle, column).map { String(cString: $0) } ?? ""
    }

    func int(_ column: Int32) -> Int {
        Int(sqlite3_column_int64(handle, column))
    }
}

extension Character {
    /// CJK unified ideographs (including extension A) and the iteration mark 々.
    var isKanji: Bool {
        unicodeScalars.allSatisfy {
            (0x4E00 ... 0x9FFF).contains($0.value) || (0x3400 ... 0x4DBF).contains($0.value)
                || $0.value == 0x3005
        }
    }
}
